17	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'perf-regress-ab-'));
18	  return path.join(dir, prefix);
19	}
20	
21	function readJson(p) {
22	  return JSON.parse(fs.readFileSync(p, 'utf8'));
23	}
24	
25	const SIDE_KEYS = ['command', 'runs', 'warmup', 'timeout_ms', 'unit', 'samples', 'summary', 'errors'];
26	const COMPARISON_KEYS = ['baseline_summary', 'candidate_summary', 'delta', 'welch', 'decision', 'attribution'];
27	
28	test('成功：退出码 0，顶层字段与两侧 collect 口径正确，comparison 完整', () => {
29	  const out = withTempFile('ok.json');
30	  const r = runCli(['--baseline-command', 'true', '--candidate-command', 'true',
31	    '--runs', '3', '--warmup', '1', '--timeout-ms', '5000', '--output', out]);
32	  assert.equal(r.status, 0, r.stderr);
33	
34	  const report = readJson(out);
35	  assert.deepEqual(Object.keys(report), ['baseline', 'candidate', 'comparison']);
36	
37	  for (const sideName of ['baseline', 'candidate']) {
38	    const side = report[sideName];
39	    assert.deepEqual(Object.keys(side), SIDE_KEYS);
40	    assert.equal(side.command, 'true');
41	    assert.equal(side.runs, 3);
42	    assert.equal(side.warmup, 1);
43	    assert.equal(side.timeout_ms, 5000);
44	    assert.equal(side.unit, 'ns');
45	    assert.equal(side.errors.length, 0);
46	    assert.equal(side.samples.length, 3);
47	    side.samples.forEach((s, i) => {
48	      assert.deepEqual(Object.keys(s), ['index', 'started_at', 'duration_ns', 'exit_code']);
49	      assert.equal(s.index, i);
50	      assert.equal(s.exit_code, 0);
51	      assert.equal(Number.isSafeInteger(s.duration_ns), true);
52	    });
53	    assert.equal(side.summary.count, 3);
54	  }
55	
56	  assert.deepEqual(Object.keys(report.comparison), COMPARISON_KEYS);
57	  assert.equal(report.comparison.baseline_summary.count, 3);
58	  assert.equal(report.comparison.candidate_summary.count, 3);
59	  assert.ok(['regression', 'improvement', 'no_material_change', 'not_significant']
60	    .includes(report.comparison.decision));
61	  // delta.mean 下含 confidence_interval，level 随默认 alpha=0.05
62	  const ci = report.comparison.delta.mean.confidence_interval;
63	  assert.deepEqual(Object.keys(ci),
64	    ['level', 'lower_ns', 'upper_ns', 'lower_percent', 'upper_percent']);
65	  assert.equal(ci.level, 0.95);
66	  assert.ok(ci.lower_ns <= ci.upper_ns);
67	  assert.equal('confidence_interval' in report.comparison.delta.median, false);
68	});
