70	test('comparison 为 null（有效样本不足）时不提供 confidence_interval', () => {
71	  const out = withTempFile('nullcmp.json');
72	  const r = runCli(['--baseline-command', 'true', '--candidate-command', 'exit 7',
73	    '--runs', '2', '--timeout-ms', '5000', '--output', out]);
